-- Run once in a Snowsight worksheet as ACCOUNTADMIN.
-- Before running: replace <PASTE_PUBLIC_KEY_HERE> (3 places) with your public key body,
-- i.e. the contents of agentic_key.pub WITHOUT the -----BEGIN/END----- lines, on one line.
USE ROLE ACCOUNTADMIN;

-- 1. Compute + cost guardrail
CREATE WAREHOUSE IF NOT EXISTS AGENTIC_WH
  WAREHOUSE_SIZE = 'XSMALL' AUTO_SUSPEND = 60 AUTO_RESUME = TRUE INITIALLY_SUSPENDED = TRUE;
CREATE OR REPLACE RESOURCE MONITOR AGENTIC_MONITOR WITH CREDIT_QUOTA = 20
  TRIGGERS ON 80 PERCENT DO NOTIFY ON 100 PERCENT DO SUSPEND;
ALTER WAREHOUSE AGENTIC_WH SET RESOURCE_MONITOR = AGENTIC_MONITOR;

-- 2. Environments = databases
CREATE DATABASE IF NOT EXISTS AGENTIC_RAW;
CREATE SCHEMA   IF NOT EXISTS AGENTIC_RAW.ECOM;
CREATE DATABASE IF NOT EXISTS AGENTIC_DEV;    -- local dev + per-PR CI schemas
CREATE DATABASE IF NOT EXISTS AGENTIC_PROD;   -- only the CD pipeline writes here

-- 3. Roles (least privilege: the 'agent-facing' role cannot touch PROD)
CREATE ROLE IF NOT EXISTS AGENTIC_LOADER_ROLE;
CREATE ROLE IF NOT EXISTS DBT_CI_ROLE;
CREATE ROLE IF NOT EXISTS DBT_PROD_ROLE;

GRANT USAGE ON WAREHOUSE AGENTIC_WH TO ROLE AGENTIC_LOADER_ROLE;
GRANT USAGE ON WAREHOUSE AGENTIC_WH TO ROLE DBT_CI_ROLE;
GRANT USAGE ON WAREHOUSE AGENTIC_WH TO ROLE DBT_PROD_ROLE;

-- loader: writes RAW
GRANT USAGE ON DATABASE AGENTIC_RAW TO ROLE AGENTIC_LOADER_ROLE;
GRANT USAGE, CREATE TABLE, CREATE STAGE, CREATE FILE FORMAT
  ON SCHEMA AGENTIC_RAW.ECOM TO ROLE AGENTIC_LOADER_ROLE;

-- dbt roles: read RAW
GRANT USAGE ON DATABASE AGENTIC_RAW TO ROLE DBT_CI_ROLE;
GRANT USAGE ON DATABASE AGENTIC_RAW TO ROLE DBT_PROD_ROLE;
GRANT USAGE ON SCHEMA AGENTIC_RAW.ECOM TO ROLE DBT_CI_ROLE;
GRANT USAGE ON SCHEMA AGENTIC_RAW.ECOM TO ROLE DBT_PROD_ROLE;
GRANT SELECT ON FUTURE TABLES IN SCHEMA AGENTIC_RAW.ECOM TO ROLE DBT_CI_ROLE;
GRANT SELECT ON FUTURE TABLES IN SCHEMA AGENTIC_RAW.ECOM TO ROLE DBT_PROD_ROLE;

-- dbt roles: write their own environment only
GRANT USAGE, CREATE SCHEMA ON DATABASE AGENTIC_DEV  TO ROLE DBT_CI_ROLE;
GRANT USAGE, CREATE SCHEMA ON DATABASE AGENTIC_PROD TO ROLE DBT_PROD_ROLE;

-- 4. Service users (key-pair auth, no passwords). Same key on all three is OK for a prototype only.
CREATE USER IF NOT EXISTS DBT_LOADER_USER TYPE = SERVICE DEFAULT_ROLE = AGENTIC_LOADER_ROLE
  DEFAULT_WAREHOUSE = AGENTIC_WH RSA_PUBLIC_KEY = '<>';
CREATE USER IF NOT EXISTS DBT_CI_USER TYPE = SERVICE DEFAULT_ROLE = DBT_CI_ROLE
  DEFAULT_WAREHOUSE = AGENTIC_WH RSA_PUBLIC_KEY = '<>';
CREATE USER IF NOT EXISTS DBT_PROD_USER TYPE = SERVICE DEFAULT_ROLE = DBT_PROD_ROLE
  DEFAULT_WAREHOUSE = AGENTIC_WH RSA_PUBLIC_KEY = '<>';

GRANT ROLE AGENTIC_LOADER_ROLE TO USER DBT_LOADER_USER;
GRANT ROLE DBT_CI_ROLE         TO USER DBT_CI_USER;
GRANT ROLE DBT_PROD_ROLE       TO USER DBT_PROD_USER;

-- 5. Sanity check
SHOW GRANTS TO ROLE DBT_CI_ROLE;
